#pragma once
#include <vector>
#include <queue>
#include <stack>
#include <deque>
#include <limits>

void dfs(std::vector<int> const& A, int node, size_t N, std::vector<bool> &visited) {
   visited[node] = true;
   for (int i = 0; i < N; i += 1) {
      if (A[node * N + i] == 1 && !visited[i]) {
         dfs(A, i, N, visited);
      }
   }
