int largestComponent(std::vector<int> const& A, size_t N) {
   std::vector<bool> visited(N, false);
   int maxCount = 0;

   // Use OpenMP for parallel processing of unvisited nodes
   #pragma omp parallel
   {
      int localMaxCount = 0;
      #pragma omp for
      for (int i = 0; i < N; i += 1) {
         if (!visited[i]) {
            int count = 0;
            dfs(A, i, N, visited, count);
            localMaxCount = std::max(localMaxCount, count);
         }
      }
      // Reduction to find the maximum count across threads
      #pragma omp atomic
      maxCount = std::max(maxCount, localMaxCount);
   }
   return maxCount;
}

