   #pragma omp parallel
   {
      int localMaxCount = 0;
      #pragma omp for
      for (int i = 0; i < N; i += 1) {
         if (!visited[i]) {
            int count = 0;
            dfs(A, i, N, visited, count);
            localMaxCount = std::max(localMaxCount, count);
         }
      }
      #pragma omp critical
      maxCount = std::max(maxCount, localMaxCount);
