      auto [current, pathLength] = queue.front();
      queue.pop();

      if (current == dest) {
         return pathLength;
      }

      // Check all adjacent vertices in a single loop
      for (int i = 0; i < N; ++i) {
         if (A[current*N + i] &&!visited[i]) {
               visited[i] = true;
               queue.push({i, pathLength + 1});
         }
      }
   }

   return std::numeric_limits<int>::max();
}

