#pragma once
#include <array>
#include <vector>
#include <immintrin.h>

void binsBy10Count(std::vector<double> const& x, std::array<size_t, 10> &bins) {
    // Initialize bins to zero
    for (size_t i = 0; i < 10; i++) {
        bins[i] = 0;
    }

    // Process data in chunks of 4 using SIMD instructions
    size_t i = 0;
    for (; i + 4 <= x.size(); i += 4) {
        __m256d values = _mm256_loadu_pd(&x[i]);
        __m256d divisor = _mm256_set1_pd(10.0);
        __m256d quotients = _mm256_floor_pd(_mm256_div_pd(values, divisor));
        int mask = _mm256_movemask_pd(_mm256_cmp_pd(quotients, _mm256_set1_pd(9.0), _CMP_LE_OQ));

        // Increment bins based on the comparison results
        bins[0] += (mask & 0b00000001)? 1 : 0;
        bins[1] += (mask & 0b00000010)? 1 : 0;
        bins[2] += (mask & 0b00000100)? 1 : 0;
        bins[3] += (mask & 0b00001000)? 1 : 0;
        bins[4] += (mask & 0b00010000)? 1 : 0;
        bins[5] += (mask & 0b00100000)? 1 : 0;
        bins[6] += (mask & 0b01000000)? 1 : 0;
        bins[7] += (mask & 0b10000000)? 1 : 0;
    }

    // Handle remaining elements
    for (; i < x.size(); i++) {
        size_t bin = x[i] / 10;
        bins[bin]++;
    }
}

