void binsBy10Count(std::vector<double> const& x, std::array<size_t, 10> &bins) {
    // Use SIMD to process 4 elements at a time
    for (size_t i = 0; i < x.size(); i += 4) {
        __m256d values = _mm256_loadu_pd(&x[i]);
        __m256d divisor = _mm256_set1_pd(10.0);
        __m256d quotients = _mm256_floor_pd(_mm256_div_pd(values, divisor));
        __m256d integer_part = _mm256_cvttpd_epi64(quotients);
        __m128i int_part_low = _mm256_extracti128_si256(integer_part, 0);
        __m128i int_part_high = _mm256_extracti128_si256(integer_part, 1);
        __m128i counts_low = _mm_cvtepi32_epi8(int_part_low);
        __m128i counts_high = _mm_cvtepi32_epi8(int_part_high);
        // Use AVX2 to store results in bins
        _mm_storeu_si128((__m128i*)&bins[0], _mm_add_epi8(_mm_loadu_si128((__m128i*)&bins[0]), counts_low));
        _mm_storeu_si128((__m128i*)&bins[4], _mm_add_epi8(_mm_loadu_si128((__m128i*)&bins[4]), counts_high));
    }
    // Handle remaining elements
    for (size_t i = (x.size() / 4) * 4; i < x.size(); i += 1) {
        const size_t bin = x[i] / 10;
        bins[bin] += 1;
    }
}

