#pragma once

#include <vector>
#include <numeric>
#include <omp.h>

void reversePrefixSum(std::vector<int> const& x, std::vector<int> &output) {
    size_t n = x.size();
    if (n == 0) return;

    // Use a temporary vector for the reversed elements
    std::vector<int> reverseX(n);

    // Reverse the elements in a single loop
    for (size_t i = 0; i < n; i++) {
        reverseX[i] = x[n - 1 - i];
    }

    // Use OpenMP for parallel computation of inclusive scan
    #pragma omp parallel
    {
        // Use local storage for each thread's partial results
        std::vector<int> localResults(n);

        // Compute the inclusive scan in a single pass
        std::inclusive_scan(reverseX.begin(), reverseX.end(), localResults.begin());

        // Combine the results from each thread into the output vector
        #pragma omp critical
        {
            for (size_t i = 0; i < n; i++) {
                output[i] = localResults[i];
            }
        }
    }
}

