*/
double sumOfPrefixSum(std::vector<double> const& x) {
    if (x.empty()) return 0.0;
    if (x.size() < 1000) {
        std::vector<double> prefixSum(x.size());
        std::inclusive_scan(x.begin(), x.end(), prefixSum.begin());
