    // Process 4 elements at a time using SIMD instructions
    for (; i + 4 <= size; i += 4) {
        __m128i values = _mm_loadu_si128((__m128i*)&x[i]);
        __m128i even_mask = _mm_and_si128(values, _mm_set1_epi32(1));
        __m128i odd_mask = _mm_xor_si128(even_mask, _mm_set1_epi32(-1));
        __m128i halved_evens = _mm_srai_epi32(values, 1);
        __m128i results = _mm_blendv_epi8(halved_evens, odd_mask, even_mask);
        _mm_storeu_si128((__m128i*)&x[i], results);
