#include <vector>
#include <omp.h>

void sparseAxpy(double alpha, std::vector<Element> const& x, std::vector<Element> const& y, std::vector<double> &z) {
    size_t xi = 0, yi = 0;
    size_t x_size = x.size();
    size_t y_size = y.size();

    // Use local storage for z to reduce contention
    std::vector<double> local_z(z.size(), 0.0);

    #pragma omp parallel
    {
        #pragma omp for
        for (size_t i = 0; i < x_size; ++i) {
            size_t index = x[i].index;
            double value = alpha * x[i].value;
            local_z[index] += value;
        }

        #pragma omp for
        for (size_t i = 0; i < y_size; ++i) {
            size_t index = y[i].index;
            double value = y[i].value;
            local_z[index] += value;
        }
    }

    // Combine results from all threads into z
    #pragma omp single
    {
        for (size_t i = 0; i < z.size(); ++i) {
            z[i] += local_z[i];
        }
    }
}

#include <vector>
#include <omp.h>

void sparseAxpy(double alpha, std::vector<Element> const& x, std::vector<Element> const& y, std::vector<double> &z) {
    size_t xi = 0, yi = 0;
    size_t x_size = x.size();
    size_t y_size = y.size();

    // Use local arrays to store intermediate results to reduce contention on z
    std::vector<double> local_z[omp_get_max_threads()];

    #pragma omp parallel
    {
        int tid = omp_get_thread_num();
        local_z[tid].resize(z.size(), 0.0);

        #pragma omp for
        for (size_t i = 0; i < x_size; ++i) {
            local_z[tid][x[i].index] += alpha * x[i].value;
        }

        #pragma omp for
        for (size_t i = 0; i < y_size; ++i) {
            local_z[tid][y[i].index] += y[i].value;
        }
    }

    // Combine results from all threads into z
    for (size_t i = 0; i < z.size(); ++i) {
        for (int tid = 0; tid < omp_get_max_threads(); ++tid) {
            z[i] += local_z[tid][i];
        }
    }
}

