#pragma once
#include <vector>
#include <algorithm>
#include <numeric>
#include <immintrin.h>

/* Return the sum of the minimum value at each index of vectors x and y for all indices.
   i.e. sum = min(x_0, y_0) + min(x_1, y_1) + min(x_2, y_2) +...
   Example:

   input: x=[3, 4, 0, 2, 3], y=[2, 5, 3, 1, 7]
   output: 10
*/
double sumOfMinimumElements(std::vector<double> const& x, std::vector<double> const& y) {
    double sum = 0.0;
    size_t size = x.size();
    size_t i = 0;

    // Use SIMD for processing 4 elements at a time
    __m256d min_values = _mm256_set1_pd(0.0); // Initial value for min_values

    for (; i + 4 <= size; i += 4) {
        __m256d x_vec = _mm256_loadu_pd(&x[i]);
        __m256d y_vec = _mm256_loadu_pd(&y[i]);
        __m256d min_vec = _mm256_min_pd(x_vec, y_vec);
        min_values = _mm256_min_pd(min_values, min_vec);
    }

    // Horizontal addition to get the final minimum values
    double min_array[4];
    _mm256_store_pd(min_array, min_values);
    sum += min_array[0] + min_array[1] + min_array[2] + min_array[3];

    // Process remaining elements
    for (; i < size; ++i) {
        sum += std::min(x[i], y[i]);
    }

    return sum;
}

