/* Return the sum of the minimum value at each index of vectors x and y for all indices.
   i.e. sum = min(x_0, y_0) + min(x_1, y_1) + min(x_2, y_2) +...
   Example:

   input: x=[3, 4, 0, 2, 3], y=[2, 5, 3, 1, 7]
   output: 10
*/
double sumOfMinimumElements(std::vector<double> const& x, std::vector<double> const& y) {
    size_t size = x.size();
    double sum = 0.0;
    size_t i = 0;

    // Use SIMD for processing in blocks of 4
    for (; i + 4 <= size; i += 4) {
        __m256d x_vec = _mm256_loadu_pd(&x[i]);
        __m256d y_vec = _mm256_loadu_pd(&y[i]);
        __m256d min_vec = _mm256_min_pd(x_vec, y_vec);
        __m128d min_low = _mm256_extractf128_pd(min_vec, 0);
        __m128d min_high = _mm256_extractf128_pd(min_vec, 1);
        __m128d sum_vec = _mm_add_pd(_mm_loadu_pd(&sum), min_low);
        sum_vec = _mm_add_pd(sum_vec, min_high);
        _mm_storeu_pd(&sum, sum_vec);
    }

    // Handle remaining elements
    for (; i < size; ++i) {
        sum += std::min(x[i], y[i]);
    }

    return sum;
}

