    triangleAreas.reserve(points.size() * (points.size() - 1) * (points.size() - 2) / 6);
    for (size_t i = 0; i < points.size(); i++) {
        for (size_t j = i + 1; j < points.size(); j++) {
            for (size_t k = j + 1; k < points.size(); k++) {
                triangleAreas.push_back(triArea(points[i], points[j], points[k]));
            }
        }
    }

    // Find the minimum area by searching through the precomputed areas
    for (double area : triangleAreas) {
        if (area < minArea) {
            minArea = area;
        }
    }

    return minArea;
}

