   output: 5.5
*/
double smallestArea(std::vector<Point> const& points) {
    // The polygon needs to have at least three points
    if (points.size() < 3)   {
        return 0;
    }

    double minArea = std::numeric_limits<double>::max();
    for (size_t i = 0; i < points.size() - 2; i++) {
        for (size_t j = i + 1; j < points.size() - 1; j++) {
            for (size_t k = j + 1; k < points.size(); k++) {
                // Calculate the area of the triangle using Heron's formula
                double a = std::sqrt((points[i].x - points[j].x) * (points[i].x - points[j].x) + (points[i].y - points[j].y) * (points[i].y - points[j].y));
