    std::sort(pointsSorted.begin(), pointsSorted.end(), [](Point const& a, Point const& b) {
        return a.x < b.x || (a.x == b.x && a.y < b.y);
    });

    // Helper function to calculate the cross product of two points
    auto CrossProduct = [](Point const& a, Point const& b, Point const& c) {
        return (c.x - a.x) * (b.y - a.y) - (c.y - a.y) * (b.x - a.x);
    };

    // Helper function to determine if a point is on the same line as two other points
    auto Collinear = [](Point const& a, Point const& b, Point const& c) {
        return CrossProduct(a, b, c) == 0;
    };

    // Helper function to calculate the distance between two points
    auto Distance = [](Point const& a, Point const& b) {
        return std::sqrt((a.x - b.x) * (a.x - b.x) + (a.y - b.y) * (a.y - b.y));
    };

    // Helper function to calculate the angle between three points
    auto Angle = [](Point const& a, Point const& b, Point const& c) {
        double dx1 = b.x - a.x;
        double dy1 = b.y - a.y;
        double dx2 = c.x - b.x;
        double dy2 = c.y - b.y;
        double dot = dx1 * dx2 + dy1 * dy2;
        double cross = dx1 * dy2 - dy1 * dx2;
        return std::atan2(cross, dot);
    };

    // Build the upper hull
    std::vector<Point> upperHull;
    upperHull.reserve(pointsSorted.size());
    upperHull.push_back(pointsSorted[0]);
    upperHull.push_back(pointsSorted[1]);

    for (size_t i = 2; i < pointsSorted.size(); i++) {
        while (upperHull.size() > 1
               && CrossProduct(upperHull[upperHull.size() - 2],
                               upperHull[upperHull.size() - 1],
                               pointsSorted[i]) <= 0) {
            upperHull.pop_back();
        }
        upperHull.push_back(pointsSorted[i]);
    }

