    std::vector<Point> lowerHull;
    lowerHull.reserve(pointsSorted.size());
    lowerHull.push_back(pointsSorted[pointsSorted.size() - 1]);
    lowerHull.push_back(pointsSorted[pointsSorted.size() - 2]);

    for (size_t i = pointsSorted.size() - 3; i < pointsSorted.size(); i--) {
        while (lowerHull.size() > 1
               && CrossProduct(lowerHull[lowerHull.size() - 2],
                               lowerHull[lowerHull.size() - 1],
                               pointsSorted[i]) <= 0) {
            lowerHull.pop_back();
        }
        lowerHull.push_back(pointsSorted[i]);
    }

    // Combine the upper and lower hulls to form the convex hull
    upperHull.insert(upperHull.end(), lowerHull.begin(), lowerHull.end());

    // Remove collinear points from the hull
    std::vector<Point> finalHull;
    finalHull.reserve(upperHull.size());
    finalHull.push_back(upperHull[0]);

    for (size_t i = 1; i < upperHull.size(); i++) {
        if (!Collinear(finalHull.back(), upperHull[i], upperHull[(i + 1) % upperHull.size()])) {
            finalHull.push_back(upperHull[i]);
        }
    }

    // If the final hull has less than 3 points, return all points
    if (finalHull.size() < 3) {
        hull = finalHull;
        return;
    }

    // Sort the final hull by angle to ensure a consistent order
    std::sort(finalHull.begin(), finalHull.end(), [&finalHull](Point const& a, Point const& b) {
        return Angle(finalHull[0], a, b) < 0;
    });

    hull = finalHull;
}

