/* Compute one iteration of a 3-point 1D jacobi stencil on `input`. Store the results in `output`.
   Each element of `input` will be averaged with its two neighbors and stored in the corresponding element of `output`.
   i.e. output[i] = (input[i-1]+input[i]+input[i+1])/3
   Replace with 0 when reading past the boundaries of `input`.
   Example:

   input: [9, -6, -1, 2, 3]
   output: [1, 2/3, -5/3, 4/3, 5/3]
*/
void jacobi1D(std::vector<double> const& input, std::vector<double> &output) {
    size_t i = 0;
    for (; i + 3 < input.size(); i += 4) {
        __m256d input_vec = _mm256_loadu_pd(&input[i]);
        __m256d sum_vec = _mm256_setzero_pd();

        // Sum the neighbors
        if (i > 0) {
            __m256d prev_vec = _mm256_loadu_pd(&input[i - 1]);
            sum_vec = _mm256_add_pd(sum_vec, prev_vec);
        }
        if (i + 1 < input.size()) {
            __m256d next_vec = _mm256_loadu_pd(&input[i + 1]);
            sum_vec = _mm256_add_pd(sum_vec, next_vec);
        }

        // Add the current element
        sum_vec = _mm256_add_pd(sum_vec, input_vec);

        // Compute the average
        __m256d avg_vec = _mm256_div_pd(sum_vec, _mm256_set1_pd(3.0));

        // Store the result
        _mm256_storeu_pd(&output[i], avg_vec);
    }

    // Handle remaining elements
    for (; i < input.size(); i++) {
        double sum = input[i];
        if (i > 0) {
            sum += input[i - 1];
        }
        if (i < input.size() - 1) {
            sum += input[i + 1];
        }
        output[i] = sum / 3.0;
    }
}

