#include <vector>
#include <immintrin.h>

void jacobi2D(std::vector<double> const& input, std::vector<double> &output, size_t N) {
    // Loop unrolling for performance
    for (size_t i = 0; i < N; i++) {
        for (size_t j = 0; j < N; j += 4) {
            __m256d sum = _mm256_setzero_pd();

            // Compute sum for j
            if (j > 0) {
                sum = _mm256_add_pd(sum, _mm256_loadu_pd(&input[i * N + (j - 1)]));
            }
            if (j < N - 1) {
                sum = _mm256_add_pd(sum, _mm256_loadu_pd(&input[i * N + (j + 1)]));
            }
            if (i > 0) {
                sum = _mm256_add_pd(sum, _mm256_loadu_pd(&input[(i - 1) * N + j]));
            }
            if (i < N - 1) {
                sum = _mm256_add_pd(sum, _mm256_loadu_pd(&input[(i + 1) * N + j]));
            }
            sum = _mm256_add_pd(sum, _mm256_loadu_pd(&input[i * N + j]));

            // Store results
            _mm256_storeu_pd(&output[i * N + j], _mm256_div_pd(sum, _mm256_set1_pd(5.0)));

            // Handle remaining elements
            if (j + 1 < N) {
                _mm256_storeu_pd(&output[i * N + j + 1], _mm256_div_pd(_mm256_loadu_pd(&input[i * N + j + 1]), _mm256_set1_pd(5.0)));
            }
            if (j + 2 < N) {
                _mm256_storeu_pd(&output[i * N + j + 2], _mm256_div_pd(_mm256_loadu_pd(&input[i * N + j + 2]), _mm256_set1_pd(5.0)));
            }
            if (j + 3 < N) {
                _mm256_storeu_pd(&output[i * N + j + 3], _mm256_div_pd(_mm256_loadu_pd(&input[i * N + j + 3]), _mm256_set1_pd(5.0)));
            }
        }
    }
}

