   output: y=[1, -3]
*/
void gemv(std::vector<double> const& A, std::vector<double> const& x, std::vector<double> &y, size_t M, size_t N) {
   // Initialize y to zero
   for (size_t i = 0; i < M; i++) {
      y[i] = 0;
   }

   // Use SIMD instructions for inner loop to improve performance
   for (size_t i = 0; i < M; i++) {
      __m256d y_val = _mm256_setzero_pd();
      for (size_t j = 0; j < N; j += 4) {
         __m256d a_vec = _mm256_loadu_pd(&A[i * N + j]);
         __m256d x_vec = _mm256_loadu_pd(&x[j]);
         y_val = _mm256_fmadd_pd(a_vec, x_vec, y_val);
      }
      // Horizontal addition of 4 SIMD values to get final result
      double temp[4];
      _mm256_storeu_pd(temp, y_val);
      y[i] += temp[0] + temp[1] + temp[2] + temp[3];
   }
}

