void sortComplexByMagnitude(std::vector<std::complex<double>> &x) {
    // Use SIMD for sorting complex numbers with magnitude less than 16
    const size_t threshold = 16;
    if (x.size() < threshold) {
        std::sort(x.begin(), x.end(), [](const std::complex<double> &a, const std::complex<double> &b) {
            return std::abs(a) < std::abs(b);
        });
        return;
    }

    // Use insertion sort for small sizes
    if (x.size() < 16) {
        for (size_t i = 1; i < x.size(); ++i) {
            std::complex<double> key = x[i];
            size_t j = i - 1;
            while (j < x.size() && std::abs(x[j]) > std::abs(key)) {
                x[j + 1] = x[j];
                --j;
            }
            x[j + 1] = key;
        }
        return;
    }

    // Use optimized insertion sort for larger sizes
    for (size_t i = 1; i < x.size(); i += 2) {
        // Load the first complex number
