/* Find the k-th smallest element of the vector x.
   Example:

   input: x=[1, 7, 6, 0, 2, 2, 10, 6], k=4
   output: 6
*/
int findKthSmallest(std::vector<int> const& x, int k) {
    std::vector<int> x_copy = x;
    int n = x_copy.size();
    if (n < 1000) {
        std::sort(x_copy.begin(), x_copy.end());
        return x_copy[k-1];
    }

    // Use insertion sort for small sizes to avoid overhead of quicksort
    if (n < 16) {
        for (int i = 1; i < n; ++i) {
            int key = x_copy[i];
            int j = i - 1;
            while (j >= 0 && x_copy[j] > key) {
                x_copy[j + 1] = x_copy[j];
                --j;
            }
            x_copy[j + 1] = key;
        }
        return x_copy[k-1];
    }

    // Use median of three pivot selection to improve partitioning
    int mid = n / 2;
    if (x_copy[0] > x_copy[mid]) std::swap(x_copy[0], x_copy[mid]);
    if (x_copy[mid] > x_copy[n - 1]) std::swap(x_copy[mid], x_copy[n - 1]);
    if (x_copy[0] > x_copy[mid]) std::swap(x_copy[0], x_copy[mid]);
    std::swap(x_copy[mid], x_copy[n - 1]); // Place pivot
    int pivot = x_copy[n - 1];

    int left = 0;
    int right = n - 2;
    int i = 0;

    // Partitioning loop
    while (i <= right) {
        if (x_copy[i] < pivot) {
            std::swap(x_copy[i], x_copy[left]);
            ++left;
            ++i;
        } else if (x_copy[i] > pivot) {
            std::swap(x_copy[i], x_copy[right]);
            --right;
        } else {
            ++i;
        }
    }
    std::swap(x_copy[left], x_copy[n - 1]); // Place pivot

    // Recursive calls for smaller partitions
    if (k == left + 1) {
        return pivot;
    } else if (k <= left) {
        return findKthSmallest(std::vector<int>(x_copy.begin(), x_copy.begin() + left), k);
    } else {
        return findKthSmallest(std::vector<int>(x_copy.begin() + left + 1, x_copy.end()), k - left - 1);
    }
}

