   output: true
*/
bool contains(std::vector<int> const& x, int target) {
    if (x.empty()) return false;

    // Use sequential search for small vectors
    if (x.size() < 16) {
        return std::find(x.begin(), x.end(), target)!= x.end();
    }

    // Use parallel binary search for larger vectors
    bool result = false;
