/* Return true if the vector x contains the value `target`. Return false otherwise.
   Examples:

   input: x=[1, 8, 2, 6, 4, 6], target=3
   output: false

   input: x=[1, 8, 2, 6, 4, 6], target=8
   output: true
*/
bool contains(std::vector<int> const& x, int target) {
    // Use binary search for sorted vectors
    if (std::is_sorted(x.begin(), x.end())) {
        return std::binary_search(x.begin(), x.end(), target);
    }
    // Linear search for unsorted vectors
    return std::find(x.begin(), x.end(), target)!= x.end();
}

